IO.Schema(node_id='Flux2ImageNode', display_name='Flux.2 Image', category='partner/image/BFL', description='Generate images via Flux.2 [pro] or Flux.2 [max] from a prompt and optional reference images.', inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Prompt for the image generation or edit'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Flux.2 [pro]', _flux2_model_inputs()), IO.DynamicCombo.Option('Flux.2 [max]', _flux2_model_inputs())]), IO.Int.Input('seed', default=0, min=0, max=18446744073709551615, control_after_generate=True, tooltip='The random seed used for creating the noise.')], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.width', 'model.height'], input_groups=['model.images']), expr='
                (
                  $isMax := widgets.model = "flux.2 [max]";
                  $MP := 1024 * 1024;
                  $w := $lookup(widgets, "model.width");
                  $h := $lookup(widgets, "model.height");
                  $outMP := $max([1, $floor((($w * $h) + $MP - 1) / $MP)]);
                  $outputCost := $isMax
                    ? (0.07 + 0.03 * ($outMP - 1))
                    : (0.03 + 0.015 * ($outMP - 1));
                  $refMin := $isMax ? 0.03 : 0.015;
                  $refMax := $isMax ? 0.24 : 0.12;
                  $hasRefs := $lookup(inputGroups, "model.images") > 0;
                  $hasRefs
                    ? {
                        "type": "range_usd",
                        "min_usd": $outputCost + $refMin,
                        "max_usd": $outputCost + $refMax,
                        "format": { "approximate": true }
                      }
                    : {"type": "usd", "usd": $outputCost}
                )
                '))

